  const desconto=num(row.VALOR_DESCONTO,0);
  const icmsSt=num(row.VALOR_ICMS_ST,0);
  const ipi=num(row.VALOR_IPI,0);
  const frete=num(row.VALOR_FRETE,0);
  const acres=num(row.VALOR_ACRESCIMOS,0);
