    if(v.clienteId){ clienteQtd[v.clienteId]=(clienteQtd[v.clienteId]||0)+1; if(!ultimo[v.clienteId]||new Date(v.data||0)>new Date(ultimo[v.clienteId]||0)) ultimo[v.clienteId]=v.data; }
