function medidoresAtivos(p){ const meds=garantirMedidores(p||{}); return MEDS.map(([k,l])=>({key:k,label:l,...meds[k]})).filter(m=>m.ativo&&!m.ocultar&&m.modalidade!=='inativo'); }
function calcMed(m, ant, atu){ const usado=Math.max(0,n(atu)-n(ant)); if(m.modalidade==='impressao') return {usado,excedente:usado,valorTotal:usado*n(m.valorPagina)+n(m.acrescimo)}; if(m.modalidade==='mes_fixo') return {usado,excedente:0,valorTotal:n(m.valorLocacao)}; const exc=Math.max(0,usado-n(m.franquia)); return {usado,excedente:exc,valorTotal:n(m.valorLocacao)+n(m.valorFranquia)+exc*n(m.valorExcedente)+n(m.acrescimo)}; }

