window.novaLeituraContrato=function(contratoId){ const c=ctr(contratoId); if(!c) return; const s=sess(); const l={id:uidSafe('lei'),empresaId:c.empresaId,contratoId:c.id,clienteId:c.clienteId,numero:seq('leitura',db.leituras||[],c.empresaId),dataLeitura:new Date().toISOString(),dataInicio:new Date().toISOString().slice(0,10),dataFim:new Date().toISOString().slice(0,10),status:'aberta',itens:[],criadoPor:s&&s.usuarioId,criadoPorNome:s&&s.usuarioNome,criadoEm:new Date().toISOString()}; db.leituras=db.leituras||[]; db.leituras.push(l); salvar(); abrirLeituraContratoDetalhe(l.id); };
