window.salvarLancamentoContador=function(leituraId){ const l=(db.leituras||[]).find(x=>x.id===leituraId); const p=prq(document.getElementById('lan-prq')?.value); if(!l||!p) return toastMsg('Selecione a impressora','error'); const key=document.getElementById('lan-med')?.value; const med=medAtivos(p).find(m=>m.key===key); if(!med) return toastMsg('Selecione o tipo ativo','error'); const atual=n(document.getElementById('lan-cont')?.value); const e=eq(p.equipamentoId)||{}; p.contadores=p.contadores||{}; const anterior=n(p.contadores[key] ?? med.contadorInicial); const r=calc(med,anterior,atual); p.contadores[key]=atual; l.itens=l.itens||[]; l.itens.push({parqueId:p.id,equipamentoId:p.equipamentoId,impressora:`${e.patrimonio||''} ${e.modelo||''}`.trim(),medidor:key,medidorLabel:med.label,modalidade:med.modalidade,anterior,atual,utilizado:r.usado,excedente:r.excedente,valorTotal:r.valorTotal}); l.valorTotal=l.itens.reduce((s,x)=>s+n(x.valorTotal),0); l.valorExcedente=l.valorTotal; salvar(); toastMsg('Lançamento salvo','success'); abrirLeituraContratoDetalhe(l.id); };
window.faturarLeituraContrato=function(leituraId){ const s=sess(); const l=(db.leituras||[]).find(x=>x.id===leituraId); if(!s||!l) return; const c=contratoLeitura(l); const cl=cli(l.clienteId||(c&&c.clienteId))||{}; const valor=(l.itens||[]).reduce((sum,x)=>sum+n(x.valorTotal),0)||n(l.valorTotal); if(valor<=0) return toastMsg('Lance os contadores antes de faturar','error'); let cr=(db.contasReceber||[]).find(x=>x.leituraId===l.id); const dados={empresaId:s.empresaId,origem:'leitura',clienteId:cl.id,descricao:`Leitura ${l.numero||''} — ${cl.nome||''}`,valor,vencimento:new Date().toISOString(),pagamentoData:null,status:'aberto',contratoId:c&&c.id,leituraId:l.id,vendaId:null,criadoPor:s.usuarioId,criadoPorNome:s.usuarioNome}; if(cr) Object.assign(cr,dados); else db.contasReceber.push({id:uidSafe('cr'),...dados}); l.status='faturado'; salvar(); toastMsg('Leitura faturada no financeiro','success'); abrirLeiturasContrato(c.id); };
